with open("region.fasta") as f:
    lines=[l.strip() for l in f if l.strip()]
seq="".join(lines[1:]).upper()
n=len(seq)

# longest repeated substring (allowing it to be the array) using suffix approach via dict for k
import collections
def longest_repeat(seq, kmin=30):
    best=0; res=None
    for k in range(kmin, 200):
        d=collections.defaultdict(list)
        found=False
        for i in range(n-k+1):
            d[seq[i:i+k]].append(i)
        for kmer,pos in d.items():
            if len(pos)>=2:
                found=True
                if k>best:
                    best=k; res=(kmer,pos)
        if not found and k>kmin+5:
            break
    return best,res
print(longest_repeat(seq))
